+// Importing till sales from CSV (ticket,soldAt,dishId,qty). The whole file is
+// checked first; one bad row or a shortage and nothing is imported. Tickets
+// already imported are skipped.
+import { AppError } from "../errors.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { consume } from "../domain/batches.js";
+import { getItem, onHand } from "../domain/items.js";
+import { parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const round3 = (n) => Math.round(n * 1000) / 1000;
+const bad = (reason) => new AppError("bad_request", { reason });
+
+/** Imports sales; returns { tickets, dishes } counts or throws naming the row. */
+export function importSales(store, text) {
+  const rows = parseCsvObjects(text);
+  const head = String(text).split(/\r?\n/).find((l) => l.trim()) ?? "";
+  const cols = head.split(",").map((h) => h.trim());
+  for (const k of HEADER) if (!cols.includes(k)) throw bad(`missing column ${k}`);
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    const dishId = Number(r.dishId);
+    const qty = Number(r.qty);
+    if (!r.ticket) throw bad(`${where}: ticket is required`);
+    const sold = Date.parse(r.soldAt);
+    if (!/^\d{4}-\d{2}-\d{2}T/.test(r.soldAt) || Number.isNaN(sold)) throw bad(`${where}: bad soldAt`);
+    const dish = Number.isInteger(dishId) ? (store.data.dishes ?? []).find((d) => d.id === dishId) : null;
+    if (!dish) throw bad(`${where}: unknown dish`);
+    if (!Number.isInteger(qty) || qty < 1) throw bad(`${where}: bad qty`);
+    return { where, ticket: r.ticket, soldAt: new Date(sold).toISOString(), dish, qty };
+  });
+  const known = new Set((store.data.sales ??= []).map((s) => s.ticket));
+  const fresh = clean.filter((c) => !known.has(c.ticket));
+  const left = new Map();
+  for (const c of fresh) {
+    for (const n of scaled(getRecipe(store, c.dish.recipeId), c.qty)) {
+      const have = left.has(n.itemId) ? left.get(n.itemId) : onHand(store, n.itemId);
+      if (have < n.qty) {
+        const item = getItem(store, n.itemId);
+        throw bad(`${c.where}: not enough ${item.name} (only ${round3(have)} ${item.unit} left)`);
+      }
+      left.set(n.itemId, round3(have - n.qty));
+    }
+  }
+  for (const c of fresh) {
+    for (const n of scaled(getRecipe(store, c.dish.recipeId), c.qty))
+      consume(store, n.itemId, n.qty, { at: c.soldAt, ref: `sale:${c.ticket}` });
+    store.data.sales.push({ id: store.nextId("sale"), ticket: c.ticket, soldAt: c.soldAt, dishId: c.dish.id, qty: c.qty });
+  }
+  return {
+    tickets: new Set(fresh.map((c) => c.ticket)).size,
+    dishes: fresh.reduce((s, c) => s + c.qty, 0),
+  };
+}
